//! Which Rust version runs each function the menus' items and the draw lists name (typed
//! tables, `rc2k_core::menu::tables`); `table_calls.rs` calls these. Kept by hand since
//! 2026-10-24 (once generated by a removed `tools/menu_tables/gen_calls.py`). An item's
//! function gets an `ItemCall` (its value, item, menu and the carried values), a screen
//! function nothing.

use crate::errors::Refused;
use rc2k_core::menu::tables::{ItemFn, ScreenFn};

